import CryptoKit
import XCTest
@testable import RemSoundCore

final class WebFunnelEnableTests:XCTestCase {
    typealias S=WebFunnelStatus;typealias Q=WebFunnelQuery
    let source=UUID(),node="mac.tail.ts.net"
    func data(_ text:String)->Data {Data(text.utf8)}
    func inspect(_ text:String,port:UInt16=6001,name:String="mac.tail.ts.net")->S.EnablePreflight {S.prepareEnable(data(text),exitStatus:0,localPort:port,node:name,source:source)}
    func config(_ target:String="http://127.0.0.1:6001",allowed:String="false")->String {"{\"TCP\":{\"443\":{\"HTTPS\":true}},\"Web\":{\"mac.tail.ts.net:443\":{\"Handlers\":{\"/\":{\"Proxy\":\"\(target)\"}}}},\"AllowFunnel\":{\"mac.tail.ts.net:443\":\(allowed)}}"}
    func testEmptySnapshotsAreReadOnlyScopedObservations(){for text in ["null","{}","{\"TCP\":{},\"Web\":null,\"AllowFunnel\":{},\"Services\":{},\"Foreground\":null}"] {guard case .ready(let value)=inspect(text) else {return XCTFail("No empty preflight")};XCTAssertTrue(value.wasEmpty);XCTAssertFalse(value.alreadyAllowed);XCTAssertEqual(value.localPort,6001);XCTAssertEqual(value.source,source);XCTAssertEqual(value.node,node);XCTAssertEqual(value.configurationDigest,Data(SHA256.hash(data:data(text))))}}
    func testOnlyExactExistingRootCanBeClassifiedMatching(){for suffix in ["","/"] {guard case .ready(let value)=inspect(config("http://127.0.0.1:6001"+suffix)) else {return XCTFail("No exact matching preflight")};XCTAssertFalse(value.wasEmpty);XCTAssertFalse(value.alreadyAllowed)}}
    func testAlreadyAllowedIsObservationNotNewOwnership(){guard case .ready(let value)=inspect(config(allowed:"true")) else {return XCTFail("No current mapping")};XCTAssertTrue(value.alreadyAllowed);XCTAssertFalse(value.wasEmpty)}
    func testForeignTargetNeverBecomesAnEmptyConfig(){for target in ["http://127.0.0.1:6002","http://localhost:6001","https://127.0.0.1:6001","http://remote.invalid:6001","http://127.0.0.1:6001/path","http://user:pass@127.0.0.1:6001"] {XCTAssertEqual(inspect(config(target)),.conflict)}}
    func testForeignNodeAndOtherPublicPortConflict(){XCTAssertEqual(inspect(config().replacingOccurrences(of:node,with:"other.tail.ts.net")),.conflict);XCTAssertEqual(inspect(config().replacingOccurrences(of:"443",with:"8443")),.conflict)}
    func testAdditionalMountOrHandlerCannotBeReplaced(){XCTAssertEqual(inspect(config().replacingOccurrences(of:"\"/\":{",with:"\"/other\":{},\"/\":{")),.conflict);XCTAssertEqual(inspect(config().replacingOccurrences(of:"\"Proxy\":",with:"\"Text\":\"other\",\"Proxy\":")),.conflict)}
    func testForegroundAndServicesAreNeverImplicitlyOwned(){for key in ["Foreground","Services"] {XCTAssertEqual(inspect("{\"\(key)\":{\"other\":{}}}"),.conflict)}}
    func testOtherTransportOrPermissionEntryConflicts(){XCTAssertEqual(inspect(config().replacingOccurrences(of:"\"TCP\":{",with:"\"TCP\":{\"8443\":{\"HTTPS\":true},")),.conflict);XCTAssertEqual(inspect(config().replacingOccurrences(of:"\"AllowFunnel\":{",with:"\"AllowFunnel\":{\"other.tail.ts.net:443\":true,")),.conflict);XCTAssertEqual(inspect(config().replacingOccurrences(of:"\"HTTPS\":true",with:"\"HTTPS\":true,\"TCPForward\":\"127.0.0.1:9\"")),.conflict)}
    func testUnknownDuplicateAndNumericBooleanRefuse(){for text in ["bad","[]","{\"Other\":true}","{\"ETag\":\"forged\"}","{\"TCP\":{},\"TCP\":{}}",config(allowed:"1"),config().replacingOccurrences(of:"\"HTTPS\":true",with:"\"HTTPS\":1")] {XCTAssertEqual(inspect(text),.unknown)}}
    func testZeroPortOrUnvalidatedNodeCannotMintObservation(){XCTAssertEqual(inspect("{}",port:0),.unknown);for name in ["","mac.tail.ts.net.evil.invalid","MAC.tail.ts.net","mac.tail.ts.net.","mac.tail.ts.net:443"] {XCTAssertEqual(inspect("{}",name:name),.unknown)}}
    func testOutputCapAndExitFailureBeforeSnapshotHashing(){XCTAssertEqual(inspect(String(repeating:" ",count:S.maximumOutputBytes+1)),.unknown);XCTAssertEqual(S.prepareEnable(data("{}"),exitStatus:1,localPort:6001,node:node,source:source),.unknown)}
    func testSnapshotDigestChangesWithRawStateAndNeverClaimsETag(){guard case .ready(let first)=inspect("{}"),case .ready(let second)=inspect("null") else {return XCTFail("No observations")};XCTAssertEqual(first.configurationDigest.count,32);XCTAssertNotEqual(first.configurationDigest,second.configurationDigest)}
    func testExistingQueryOwnerPreflightsUsingOnlyTwoReadOnlyPlans(){let f=WebFunnelQueryTests.Fixture();XCTAssertTrue(f.service.prepareEnable(f.scope){f.results.append($0)});f.pump();f.end(0,"{}");f.end(1,f.node());guard case .enablePreflight(.ready(let value))?=f.results.first else {return XCTFail("No integrated preflight")};XCTAssertEqual(value.source,f.scope.identity);XCTAssertEqual(value.localPort,f.scope.localPort);XCTAssertEqual(f.plans.map(\.arguments),[["funnel","status","--json"],["status","--json"]])}
    func testQueryConflictCannotBeReportedAsNoMatchingRoot(){let f=WebFunnelQueryTests.Fixture();XCTAssertTrue(f.service.prepareEnable(f.scope){f.results.append($0)});f.pump();f.end(0,config("http://127.0.0.1:6002"));f.end(1,f.node());XCTAssertEqual(f.results,[.enablePreflight(.conflict)])}
    func testQueryMissingNodeDoesNotMintAnIntent(){let f=WebFunnelQueryTests.Fixture();XCTAssertTrue(f.service.prepareEnable(f.scope){f.results.append($0)});f.pump();f.end(0,"{}");f.end(1,"{\"BackendState\":\"Running\"}");XCTAssertEqual(f.results,[.enablePreflight(.unknown)])}
    func testPreflightCancellationRetainsSameRawAndShutdownCredit(){let f=WebFunnelQueryTests.Fixture();XCTAssertTrue(f.service.prepareEnable(f.scope){f.results.append($0)});f.pump();XCTAssertFalse(f.start());XCTAssertTrue(f.service.shutdown{f.shutdowns += 1});f.pump();XCTAssertEqual(f.shutdowns,0);let sink=f.sinks[0];sink.stdoutClosed();sink.stderrClosed();sink.exited(0);f.pump();XCTAssertEqual(f.shutdowns,0);XCTAssertTrue(f.results.isEmpty);sink.retired();f.pump();XCTAssertEqual(f.shutdowns,1);XCTAssertEqual(f.results,[.failed(.cancelled)])}
    func testPreflightOffAndIsolationBeforeFactories(){for isolated in [false,true] {let queue=DispatchQueue(label:"test.preflight.off");var factories=0;let s=Q.Service(queue:queue,isolated:isolated,current:{_ in factories += 1;return true},launch:{_,_ in factories += 1;return nil});XCTAssertFalse(s.prepareEnable(.init(identity:UUID(),localPort:6001)){_ in XCTFail("No refused callback")});if isolated {s.setEnabled(true);XCTAssertFalse(s.prepareEnable(.init(identity:UUID(),localPort:6001)){_ in XCTFail("No isolated callback")})};queue.sync{};XCTAssertEqual(factories,0)}}
    func testStalePreflightCannotReportReadyAfterNodeReturn(){let f=WebFunnelQueryTests.Fixture();XCTAssertTrue(f.service.prepareEnable(f.scope){f.results.append($0)});f.pump();f.end(0,"{}");f.current=false;f.end(1,f.node());XCTAssertEqual(f.results,[.failed(.cancelled)])}
    func testPreflightCallbackRetainsCreditThroughItsReturn(){let f=WebFunnelQueryTests.Fixture();var called=false;XCTAssertTrue(f.service.prepareEnable(f.scope){result in guard case .enablePreflight(.ready)=result else {return XCTFail("No preflight")};called=true;XCTAssertFalse(f.service.prepareEnable(f.scope){_ in XCTFail("No reentrant admission")});XCTAssertTrue(f.service.shutdown{f.shutdowns += 1});XCTAssertEqual(f.shutdowns,0)});f.pump();f.end(0,"{}");f.end(1,f.node());XCTAssertTrue(called);XCTAssertEqual(f.shutdowns,1)}
}
